// 1. ดึงข้อมูลวันที่ปัจจุบันสำหรับใช้เป็นเวลาสร้างเอกสาร (ด้านล่างรายงาน)
const today = new Date();

// คำนวณหา "เดือน/ปี" ของ "เดือนที่แล้ว" สำหรับแสดงบนหัวรายงาน
const lastMonthDate = new Date();
lastMonthDate.setMonth(lastMonthDate.getMonth() - 1); 
const targetYear = lastMonthDate.getFullYear();

const thaiMonths = [
    'มกราคม', 'กุมภาพันธ์', 'มีนาคม', 'เมษายน', 'พฤษภาคม', 'มิถุนายน', 
    'กรกฎาคม', 'สิงหาคม', 'กันยายน', 'ตุลาคม', 'พฤศจิกายน', 'ธันวาคม'
];
const displayMonthName = thaiMonths[lastMonthDate.getMonth()];
const displayYearTH = targetYear + 543; 

let count = 0; 
let tableRows = '';

let countPending = 0;
let countApproved = 0;
let countOngoing = 0;
let countCompleted = 0;
let countCancelled = 0;

// 🌟 จุดที่แก้ไข: ตั้งค่าเริ่มต้นให้ทุกห้องเป็น 0 ไว้ก่อน
let roomCounts = {
    "ห้องประชุม 1 (ห้องเล็ก)": 0,
    "ห้องประชุม 2 (ห้องใหญ่)": 0,
    "ห้องประชุมผู้บริหาร": 0,
    "ประชุมออนไลน์ (ไม่ต้องใช้ห้อง)": 0
};

const inputData = $input.all()[0].json.data || $input.all().map(item => item.json);

// 2. วนลูปเช็คข้อมูลทุกแถว
for (let item of inputData) {
    count++;

    let reportDate = item['วันที่'] || "-";
    let startTime = item['เริ่ม'] || "-";
    let endTime = item['เสร็จสิ้น'] || "-";
    let dateTimeStr = `${reportDate}<br><span style='color: #888; font-size: 10px;'>เวลา: ${startTime} - ${endTime} น.</span>`;

    let rowBgColor = (count % 2 === 0) ? '#fafafa' : '#ffffff';

    let statusText = item['สถานะ'] || '-';
    let statusColor = '#555555'; 

    if (statusText.includes('รออนุมัติ')) {
        statusColor = '#F39C12'; 
        countPending++;
    } else if (statusText.includes('อนุมัติแล้ว') || statusText === 'อนุมัติ') {
        statusColor = '#27ae60'; 
        countApproved++;
    } else if (statusText.includes('กำลังประชุม')) {
        statusColor = '#3498db'; 
        countOngoing++;
    } else if (statusText.includes('เสร็จสิ้น')) {
        statusColor = '#7f8c8d'; 
        countCompleted++;
    } else if (statusText.includes('ยกเลิก') || statusText.includes('ไม่อนุมัติ')) {
        statusColor = '#e74c3c'; 
        countCancelled++;
    }

    // 🌟 จุดที่แก้ไข: บวดยอดห้องประชุม (ถ้าระบบเจอชื่อแปลกๆ ก็จะแอดเพิ่มให้ด้วย)
    let roomName = item['ห้องประชุม'] || 'ไม่ระบุ';
    if (roomCounts[roomName] !== undefined) {
        roomCounts[roomName]++;
    } else {
        roomCounts[roomName] = 1;
    }

    let linkHtml = '';
    if (item['ลิงก์'] && item['ลิงก์'] !== '') {
        linkHtml = `<br><a href="${item['ลิงก์']}" style="color: #3498db; font-size: 10px; text-decoration: none;">[ลิงก์ออนไลน์]</a>`;
    }

    tableRows += `
    <tr style="background-color: ${rowBgColor};">
        <td style="padding: 6px 4px; border-bottom: 1px solid #eeeeee; text-align: center; color: #555; white-space: nowrap; vertical-align: top;">${item['ID'] || '-'}</td>
        <td style="padding: 6px 4px; border-bottom: 1px solid #eeeeee; color: #333; font-weight: bold; vertical-align: top;">${item['หัวข้อประชุม'] || '-'}${linkHtml}</td>
        <td style="padding: 6px 4px; border-bottom: 1px solid #eeeeee; color: #333; vertical-align: top;">${item['ชื่อ'] || '-'}<br><span style="color: #888; font-size: 10px;">${item['แผนก'] || '-'}</span></td>
        <td style="padding: 6px 4px; border-bottom: 1px solid #eeeeee; color: #555; vertical-align: top;">${roomName}</td>
        <td style="padding: 6px 4px; border-bottom: 1px solid #eeeeee; text-align: center; color: #333; vertical-align: top;">${dateTimeStr}</td>
        <td style="padding: 6px 4px; border-bottom: 1px solid #eeeeee; text-align: center; color: #555; vertical-align: top;">${item['จำนวน'] || '-'}</td>
        <td style="padding: 6px 4px; border-bottom: 1px solid #eeeeee; text-align: center; font-weight: bold; color: ${statusColor}; white-space: nowrap; vertical-align: top;">${statusText}</td>
    </tr>`;
}

// --- สร้าง HTML สรุปยอดห้องประชุม (เรียงจากมากไปน้อย) ---
let sortedRooms = Object.entries(roomCounts).sort((a, b) => {
    if (a[0].includes('ออนไลน์') || a[0].includes('ไม่ต้องใช้ห้อง')) return 1; 
    if (b[0].includes('ออนไลน์') || b[0].includes('ไม่ต้องใช้ห้อง')) return -1; 
    return b[1] - a[1];             
});

let roomSummaryHtml = '<table style="width: 100%; border-collapse: collapse; font-size: 13px;">';
for (let i = 0; i < sortedRooms.length; i++) {
    let rm = sortedRooms[i][0];
    let rmCount = sortedRooms[i][1];
    roomSummaryHtml += `
        <tr>
            <td style="padding: 4px 0; color: #555;">${rm}</td>
            <td style="padding: 4px 0; text-align: right; font-weight: bold; color: #333;">${rmCount}</td>
        </tr>`;
}
roomSummaryHtml += '</table>';
if(sortedRooms.length === 0) roomSummaryHtml = '<div style="color: #999;">- ไม่มีข้อมูล -</div>';

const logoUrl = "https://itp1.itopfile.com/ImageServer/z_itp_02102021a937/0/0/logolv-automationz-z594084060519.png"; 

const printDate = today.toLocaleDateString('th-TH', { timeZone: 'Asia/Bangkok' });
const printTime = today.toLocaleTimeString('th-TH', { timeZone: 'Asia/Bangkok', hour: '2-digit', minute:'2-digit', hour12: false });

// 3. สร้างโครงสร้าง HTML
let html = `<!DOCTYPE html>
<html lang="th">
<head>
    <meta charset="UTF-8">
    <link href="https://fonts.googleapis.com/css2?family=Sarabun:wght@300;400;600;700&display=swap" rel="stylesheet">
    <style>
        @page { size: A4 portrait; margin: 12mm 15mm; }
        @media print {
            body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
            table { page-break-inside: auto; }
            tr { page-break-inside: avoid; page-break-after: auto; }
            thead { display: table-header-group; }
            .summary-box { page-break-inside: avoid; }
        }
        .a4-container { width: 100%; max-width: 800px; margin: 0 auto; }
    </style>
</head>
<body style="font-family: 'Sarabun', sans-serif; padding: 0; margin: 0; color: #333333; background-color: #ffffff; line-height: 1.4;">

    <div class="a4-container">
        <table style="width: 100%; border-bottom: 2px solid #F39C12; padding-bottom: 10px; margin-bottom: 15px; border-collapse: collapse;">
            <tr>
                <td style="width: 45%; vertical-align: bottom;">
                    <img src="${logoUrl}" alt="Company Logo" style="max-height: 120px; object-fit: contain;">
                </td>
                <td style="width: 55%; text-align: right; vertical-align: bottom;">
                    <h2 style="margin: 0; color: #2C3E50; font-size: 20px; font-weight: 700;">รายงานสรุปการจองห้องประชุม</h2>
                    <p style="margin: 5px 0 0 0; color: #7F8C8D; font-size: 14px;">ประจำเดือน: <strong style="color: #F39C12;">${displayMonthName} ${displayYearTH}</strong></p>
                </td>
            </tr>
        </table>

        <table style="border-collapse: collapse; width: 100%; font-size: 12px; table-layout: fixed; word-wrap: break-word;">
            <thead>
                <tr style="background-color: #F39C12; color: #ffffff;">
                    <th style="width: 9%; padding: 8px 4px; border-radius: 4px 0 0 0; text-align: center; border-bottom: 2px solid #d68910;">ID</th>
                    <th style="width: 22%; padding: 8px 4px; text-align: left; border-bottom: 2px solid #d68910;">หัวข้อประชุม</th>
                    <th style="width: 16%; padding: 8px 4px; text-align: left; border-bottom: 2px solid #d68910;">ผู้จอง</th>
                    <th style="width: 20%; padding: 8px 4px; text-align: left; border-bottom: 2px solid #d68910;">ห้องประชุม</th>
                    <th style="width: 16%; padding: 8px 4px; text-align: center; border-bottom: 2px solid #d68910;">วันที่ / เวลา</th>
                    <th style="width: 5%; padding: 8px 4px; text-align: center; border-bottom: 2px solid #d68910;">คน</th>
                    <th style="width: 12%; padding: 8px 4px; border-radius: 0 4px 0 0; text-align: center; border-bottom: 2px solid #d68910;">สถานะ</th>
                </tr>
            </thead>
            <tbody>
                ${tableRows}
            </tbody>
        </table>

        <div class="summary-box" style="margin-top: 25px; border: 1px solid #e0e0e0; border-radius: 6px; overflow: hidden;">
            <div style="background-color: #f8f9fa; border-bottom: 1px solid #e0e0e0; padding: 10px 15px; font-weight: 600; color: #2C3E50;">
                สรุปภาพรวมการจองห้องประชุม (Summary)
            </div>
            <table style="width: 100%; border-collapse: collapse;">
                <tr>
                    <td style="width: 50%; padding: 15px; vertical-align: top; border-right: 1px solid #e0e0e0;">
                        <div style="font-size: 12px; color: #7f8c8d; margin-bottom: 8px;">สรุปตามสถานะ</div>
                        <table style="width: 100%; font-size: 13px; border-collapse: collapse;">
                            <tr><td style="padding: 4px 0;"><span style="color:#F39C12;">●</span> รออนุมัติ</td><td style="text-align: right; font-weight: bold;">${countPending}</td></tr>
                            <tr><td style="padding: 4px 0;"><span style="color:#27ae60;">●</span> อนุมัติแล้ว</td><td style="text-align: right; font-weight: bold;">${countApproved}</td></tr>
                            <tr><td style="padding: 4px 0;"><span style="color:#3498db;">●</span> กำลังประชุม</td><td style="text-align: right; font-weight: bold;">${countOngoing}</td></tr>
                            <tr><td style="padding: 4px 0;"><span style="color:#7f8c8d;">●</span> ประชุมเสร็จสิ้น</td><td style="text-align: right; font-weight: bold;">${countCompleted}</td></tr>
                            <tr><td style="padding: 4px 0;"><span style="color:#e74c3c;">●</span> ยกเลิก / ไม่อนุมัติ</td><td style="text-align: right; font-weight: bold;">${countCancelled}</td></tr>
                        </table>
                        <hr style="border: 0; border-top: 1px dashed #cccccc; margin: 10px 0;">
                        <table style="width: 100%; font-size: 14px; border-collapse: collapse;">
                            <tr>
                                <td style="font-weight: 600; color: #2C3E50;">รวมจำนวนการจองทั้งสิ้น</td>
                                <td style="text-align: right; font-weight: bold; color: #F39C12; font-size: 16px;">${count} <span style="font-size: 12px; font-weight: normal; color:#555;">รายการ</span></td>
                            </tr>
                        </table>
                    </td>
                    <td style="width: 50%; padding: 15px; vertical-align: top;">
                        <div style="font-size: 12px; color: #7f8c8d; margin-bottom: 8px;">สรุปตามห้องประชุม</div>
                        ${roomSummaryHtml}
                    </td>
                </tr>
            </table>
        </div>

        <div style="text-align: right; color: #95a5a6; font-size: 11px; margin-top: 15px;">
            เอกสารสร้างอัตโนมัติเมื่อวันที่: ${printDate} เวลา ${printTime} น.
        </div>
    </div>

</body>
</html>`;

html = html.replace(/\r?\n|\r/g, "");

return [{ 
    json: { 
        reportMonthString: `${displayMonthName} ${displayYearTH}`,
        totalBookings: count,
        htmlContent: html 
    } 
}];

// 1. ดึงข้อมูลจากโหนด HTTP Request
const inputData = $input.all()[0].json.data;

// 2. คำนวณหา เดือน และ ปี ของ "เดือนที่แล้ว" เพื่อใช้เป็นเกณฑ์คัดกรอง
const now = new Date();
let lastMonth = now.getMonth() - 1;
let targetYear = now.getFullYear();

// กรณีที่เดือนปัจจุบันคือ มกราคม (0) เดือนที่แล้วจะเป็น ธันวาคม (11) ของปีก่อนหน้า
if (lastMonth < 0) {
    lastMonth = 11;
    targetYear--;
}

const resultData = [];

for (const item of inputData) {
    // 3. ตรวจสอบข้อมูลวันที่ (สมมติว่า format จาก API คือ YYYY-MM-DD)
    if (item['วันที่']) {
        // แยกส่วนวันที่ด้วย "-"
        const dateParts = item['วันที่'].split('-'); // [2026, 05, 11]

        const itemYear = parseInt(dateParts[0]);
        const itemMonth = parseInt(dateParts[1]) - 1; // ลบ 1 เพราะใน JS เดือนเริ่มที่ 0-11

        // 4. เงื่อนไข: คัดเอาเฉพาะข้อมูลที่ ปี และ เดือน ตรงกับเดือนที่แล้วเท่านั้น
        if (itemYear === targetYear && itemMonth === lastMonth) {

            // --- ทำการ Cleaning ข้อมูลวันที่และแผนกไปพร้อมกันเลย ---

            // แปลงวันที่เป็น DD/MM/YYYY
            item['วันที่'] = `${dateParts[2]}/${dateParts[1]}/${dateParts[0]}`;

            // ตัดชื่อแผนกเอาเฉพาะภาษาไทยในวงเล็บ
            if (item['แผนก']) {
                const match = item['แผนก'].match(/\((.*?)\)/);
                if (match && match[1]) {
                    item['แผนก'] = match[1];
                }
            }

            resultData.push(item);
        }
    }
}

// 5. ส่งเฉพาะข้อมูลที่ผ่านการกรองแล้วออกไป
return { json: { data: resultData } };

